export function evaluate({ inputs, time }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = 9.8;
  const t = time;
  const height = launchSpeed * t - 0.5 * gravity * t * t;
  const velocity = launchSpeed - gravity * t;

  const scale = 50;
  const originX = 120;
  const originY = 320;

  const ballY = originY - height * scale;
  const ballX = originX;

  let motionStateText = "Moving up";
  if (Math.abs(velocity) < 0.05) {
    motionStateText = "Still for an instant";
  } else if (velocity < 0) {
    motionStateText = "Moving down";
  }

  const objects = [];

  objects.push(sdk.panel({
    x: 40,
    y: 30,
    w: 560,
    h: 360,
    title: "The ball stops rising. Gravity doesn’t stop.",
    state: `Time: ${sdk.format(t, 2)} s | Height: ${sdk.format(Math.max(0, height), 2)} m`,
    id: "lane.toss"
  }));

  objects.push(sdk.axis("axis.height", {
    x: 80,
    y: 340,
    length: 260,
    orientation: "y",
    min: 0,
    max: 1.5,
    ticks: [0, 0.5, 1.0, 1.5],
    label: "Height",
    unit: "m"
  }));

  objects.push(sdk.groundMark("mark.launch", originX, originY, 40, "Launch"));

  const clampedBallY = Math.min(Math.max(ballY, 80), 340);
  objects.push(sdk.circle("ball.toss", ballX, clampedBallY, 24, {
    role: "observed"
  }));

  if (Math.abs(velocity) >= 0.05) {
    objects.push(sdk.vector("vec.v", {
      x: ballX + 20,
      y: clampedBallY
    }, {
      value: velocity,
      direction: "up"
    }, {
      scale: 12,
      minLength: 12,
      label: "v",
      role: "observed"
    }));
  }

  objects.push(sdk.vector("vec.a", {
    x: ballX - 30,
    y: clampedBallY
  }, {
    value: -gravity,
    direction: "up"
  }, {
    scale: 6,
    minLength: 15,
    label: "a",
    role: "warning"
  }));

  const calloutLines = [
    motionStateText,
    "Gravity pulls down"
  ];
  objects.push(sdk.callout(ballX + 45, clampedBallY - 20, calloutLines, {
    id: "callout.toss"
  }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "motionState", value: motionStateText },
        { id: "gravityState", value: "Pulling down" }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      velocity,
      height
    }
  };
}
